    results = []

    for _ in range(t):
        # Skip empty lines
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1

        n = int(lines[idx])
        idx += 1

        is_leaf = []
        left_child = []
        right_child = []
        value = []

        for i in range(n):
            parts = lines[idx].split()
            idx += 1

            if parts[0] == '-1':
                # Internal node
                is_leaf.append(False)
                l_idx, r_idx = int(parts[1]), int(parts[2])
                left_child.append(l_idx)
                right_child.append(r_idx)
                value.append(-1)
            else:
                # Leaf node
                is_leaf.append(True)
                left_child.append(-1)
                right_child.append(-1)
                value.append(int(parts[0]))

        result = solve_game(n, is_leaf, left_child, right_child, value)
        results.append(str(result))

    return '\n'.join(results)
