        adj[u].append((v, i, 'reverse'))  # reverse means edge should go v->u
        adj[v].append((u, i, 'forward'))  # forward means edge should go u->v

    visited = [False] * (n + 1)
    direction = [0] * m

    # BFS from source (vertex 1)
    queue = deque([1])
    visited[1] = = True

    edge_order = []

    while queue:
        u = queue.popleft()
        for v, idx, rel in adj[u]:
            if not visited[v]:
                visited[v] = True
                direction[idx] = 0 if rel == 'forward' else 1
                queue.append(v)
                edge_order.append(idx)

    # For remaining edges
    for u, v, c, idx in edges:
        if direction[idx] == 0:
            continue
        direction[idx] = direction[0] if direction[0] != 0 else 1

    return '\n'.join(map(str, direction)) + '\n' if direction[0] else '\n'.join(map(str, direction)) + '\n'
