    for u, v, w, id_ in edges:
        adj[u].append((v, id_))
        adj[v].append((u, id_))

    def can_reach(n, adj, start, end, blocked_ids):
        visited = [False] * (n + 1)
        queue = [start]
        visited[start] = True
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v, eid in adj[u]:
                if not visited[v] and eid not in blocked_ids:
                    visited[v] = True
                    queue.append(v)
                    if v == end:
                        return True
        return False

    # Check if already disconnected
    if not can_reach(n, adj, s, t, []):
        return "0\n0\n"

    # Try removing each edge individually
    for u1, v1, w1, id1 in edges:
        if not can_reach(n, adj, s, t, {id1}):
            return f"{w1}\n1\n{id1}\n"

    # Try removing pairs of edges
    best = float('inf')
    result = []

    for i in range(m):
        u1, v1, w1, id1 = edges[i]
        for j in range(i+1, m):
            u2, v2, w2, id2 = edges[j]
            if not can_reach(n, adj, s, t, {id1, id2}):
                cost = w1 + w2
                if cost < best:
                    best = cost
                    result = [id1, id2]

    if result:
        return f"{best}\n2\n{' '.join(map(str, result))}\n"

    return "-1\n"
