        for i in range(n):
            if i not in matching:
                for j in prefs[i]:
                    if j not in matching:
                        return False
            else:
                curr = matching[i]
                for j in prefs[i]:
                    if j == curr:
                        continue
                    if j not in matching:
                        return False
                    j_curr = matching[j]
                    if ranks[i][j] < ranks[i][curr] and ranks[j][i] < ranks[j][j_curr]:
                        return False
        return True

    # Find stable matching
