```python
def solution(input_str):
    import sys
    import os
    from functools import lru_cache

    MOD = 10**9 + 7
    MAX_N = 1000001

    # Precompute smallest prime factor
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    @lru_cache(maxsize=None)
    def omega(n):
        """Count distinct prime factors of n"""
        cnt = 0
        while n > 1:
            p = spf[n]
            cnt += 1
            while n % p == 0:
                n //= p
        return cnt

    @lru_cache(maxsize=None)
    def fr(n, r):
        if r == 0:
            return pow(2, omega(n), MOD)

        # fr(n, r) = sum of fr(d, r-1) for all divisors d of n
        result = 0
        for d in range(1, int(n**0.5) + 1):
            if n % d == 0:
                result = (result + fr(d, r - 1)) % MOD
                if d != n // d:
                    result = (result + fr(n // d, r - 1)) % MOD
        return result

    lines = input_str.strip().split('\n')
    q = int(lines[0])
    results = []
    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        results.append(str(fr(n, r)))
    return '\n'.join(results)
