# Your solution code here
import sys
from functools import lru_cache

sys.setrecursionlimit(3000)


def solve_tree_dp(n, edges):
    """
    Solve the tree product maximization problem using DP.

    Key insight: For each subtree, track all possible (product_of_closed_components, 
    size_of_open_component_at_root) pairs.

    When processing a child:
    - Cut edge: Child's component closes, multiply into product
    - Keep edge: Child's component merges, add sizes

    Final answer: For each (product, size) at root, compute product * size 
    (closing the root's component) and take maximum.
    """
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    @lru_cache(maxsize=None)
    def dp(u, p):
        """
        Returns set of (prod, sz) tuples where:
        - prod = product of all fully-closed component sizes in u's subtree
        - sz = size of the open component containing u (may grow up to parent)
        """
        # Base: node u itself forms component of size 1, product of closed subtrees = 1
        results = {(1, 1)}

        for v in adj[u]:
            if v == p:
                continue

            child_results = dp(v, u)
            new_results = set()

            for (prod, sz), (c_prod, c_sz) in [(r, cr) for r in results for cr in child_results]:
                # Option 1: Cut edge between u and v
                # Child v forms closed component of size c_sz
                # Child's subtree products (c_prod) multiply in
                new_results.add((prod * c_prod, c_sz))

                # Option 2: Keep edge between u and v  
                # Child v merges with u's component
                # Combined size is sz + c_sz
                new_results.add((prod * c_prod, sz + c_sz))

            results = new_results

        return results

    # Get all possible states at root
    root_states = dp(1, -1)

    # Close root's component and compute final products
    max_val = 0
    for (prod, sz) in root_states:
        # Closing root's component: multiply by its size
        final = prod * sz
        if final > max_val:
            max_val = final

    return max_val


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n = int(lines[0])
    edges = []

    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line:
            parts = line.split()
            if len(parts) == 2:
                edges.append((int(parts[0]), int(parts[1])))

    if n <= 1:
        return str(n) if n > 0 else "0"

    result = solve_tree_dp(n, edges)
    return str(result)


