def solution(text):
    """
    Solve the interactive grid navigation game.

    Args:
        text: Input string containing grid description and interaction protocol

    Returns:
        String containing sequence of moves (U, D, L, R) to reach finish cell
    """
    from collections import deque

    lines = text.strip().split('\n')
    if not lines:
        return ""

    # Parse header
    header = lines[0].split()
    if not header:
        return ""

    n = int(header[0])
    m = int(header[1])

    # Handle optional swap flags
    swapLR = int(header[2]) if len(header) > 2 else 0
    swapUD = int(header[3]) if len(header) > 3 else 0

    # Parse grid
    grid = []
    start_idx = 1 if len(header) > 2 else 1
    end_idx = start_idx + n

    for i in range(start_idx, min(end_idx, len(lines))):
        row = list(lines[i]) if i < len(lines) else ['.'] * m
        row.extend(['.'] * (m - len(row)))
        grid.append(row)

    # Pad grid
    while len(grid) < n:
        grid.append(['.'] * m)

    # Find finish position
    target = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                target = (r, c)
                break
        if target:
            break

    if not target:
        # Fallback for invalid input
        return ""

    # BFS from (0,0) to find shortest path
    visited = [[False] * m for _ in range(n)]
    parent = {}  # (r, c) -> (prev_r, prev_c, move)
    queue = deque()

    queue.append((0, 0))
    visited[0][0] = True

    # Direction mappings: (dr, dc) -> button
    directions = [
        (0, 1, 'R'),
        (0, -1, 'L'),
        (1, 0, 'D'),
        (-1, 0, 'U')
    ]

    while queue:
        r, c = queue.popleft()

        if (r, c) == target:
            # Reconstruct path
            path = []
            curr = (r, c)
            while curr != (0, 0):
                prev_r, prev_c, move = parent[curr]
                path.append(move)
                curr = (prev_r, prev_c)
            path.reverse()
            return '\n'.join(path) + '\n'

        for dr, dc, btn in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                if not visited[nr][nc] and grid[nr][nc] != '*':
                    visited[nr][nc] = True
                    parent[(nr, nc)] = (r, c, btn)
                    queue.append((nr, nc))

    return ""
